import 'jest';
import { formatTimeWithPrecision, FORMAT_TIME_DEFAULT_THRESHOLDS } from '../../src';

describe('formatTimeWithPrecision()', () => {
    const locale = {
        second: {
            singular: '${units} second',
            plural: '${units} seconds'
        },
        minute: {
            singular: '${units} minute',
            plural: '${units} minutes'
        },
        hour: {
            singular: '${units} hour',
            plural: '${units} hours'
        },
        day: {
            singular: '${units} day',
            plural: '${units} days'
        },
        week: {
            singular: '${units} week',
            plural: '${units} weeks'
        },
        month: {
            singular: '${units} month',
            plural: '${units} months'
        },
        year: {
            singular: '${units} year',
            plural: '${units} years'
        }
    };

    test('should return the 2 highest time denominations by default', () => {
        expect(formatTimeWithPrecision(123456789, FORMAT_TIME_DEFAULT_THRESHOLDS, locale)).toEqual('3 years 11 months');
    });
    test('should return the time from years down to seconds if the precision is 7', () => {
        expect(formatTimeWithPrecision(123456789, FORMAT_TIME_DEFAULT_THRESHOLDS, locale, 7)).toEqual('3 years 11 months 3 days 21 hours 33 minutes 9 seconds');
    });
});